-- Additive medical-device operations workflows. No existing records are changed.
create table public.medical_operations_definitions (
  key text not null, version integer not null check(version>0), definition jsonb not null,
  primary key(key,version), check(jsonb_typeof(definition)='object')
);
alter table public.medical_operations_definitions enable row level security;
create policy operations_definitions_read on public.medical_operations_definitions for select to authenticated using (true);
grant select on public.medical_operations_definitions to authenticated;
revoke all on public.medical_operations_definitions from anon;
revoke insert,update,delete on public.medical_operations_definitions from authenticated;
