create table public.medical_operations_cases (
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id),
 workflow_key text not null, workflow_version integer not null default 1,
 title text not null check(char_length(btrim(title)) between 3 and 180),
 state text not null default 'draft' check(state in ('draft','active','in_review','changes_requested','closed')),
 priority text not null default 'medium' check(priority in ('low','medium','high','critical')),
 owner_label text not null check(char_length(btrim(owner_label)) between 2 and 160), due_date date,
 parent_id uuid, fields jsonb not null default '{}'::jsonb check(jsonb_typeof(fields)='object' and octet_length(fields::text)<=100000),
 evidence_refs jsonb not null default '[]'::jsonb check(jsonb_typeof(evidence_refs)='array' and jsonb_array_length(evidence_refs)<=40),
 decision_note text not null default '' check(char_length(decision_note)<=4000),
 revision integer not null default 1 check(revision>0), created_by text not null default public.current_user_id(),
 last_edited_by text not null default public.current_user_id(),
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(id,organization_id), foreign key(workflow_key,workflow_version) references public.medical_operations_definitions(key,version),
 foreign key(parent_id,organization_id) references public.medical_operations_cases(id,organization_id), check(parent_id is null or parent_id<>id)
);
alter table public.medical_operations_cases enable row level security;
create policy operations_case_read on public.medical_operations_cases for select to authenticated using(public.is_org_member(organization_id));
create policy operations_case_insert on public.medical_operations_cases for insert to authenticated with check(
 public.has_org_role(organization_id,array['owner','admin','engineer']::public.member_role[]) and created_by=public.current_user_id() and state='draft' and revision=1
);
create policy operations_case_update on public.medical_operations_cases for update to authenticated
 using(public.has_org_role(organization_id,array['owner','admin','engineer','reviewer']::public.member_role[]))
 with check(public.has_org_role(organization_id,array['owner','admin','engineer','reviewer']::public.member_role[]));
grant select,insert,update on public.medical_operations_cases to authenticated;
revoke all on public.medical_operations_cases from anon;
revoke delete on public.medical_operations_cases from authenticated;

create table public.medical_operations_events (
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id),
 case_id uuid not null, revision integer not null, actor_id text not null, occurred_at timestamptz not null default clock_timestamp(),
 snapshot jsonb not null, unique(case_id,revision),
 foreign key(case_id,organization_id) references public.medical_operations_cases(id,organization_id)
);
alter table public.medical_operations_events enable row level security;
create policy operations_event_read on public.medical_operations_events for select to authenticated using(public.is_org_member(organization_id));
grant select on public.medical_operations_events to authenticated;
revoke all on public.medical_operations_events from anon;
revoke insert,update,delete on public.medical_operations_events from authenticated;

create schema labops_ops_private;
revoke all on schema labops_ops_private from public, anon, authenticated;
create function labops_ops_private.check_operations_case() returns trigger language plpgsql security invoker set search_path='' as $$
declare definition jsonb; field jsonb; ref jsonb; field_key text; val jsonb; source_table text; valid_ref boolean; actor text:=public.current_user_id();
begin
 if actor is null or not public.is_org_member(new.organization_id) then raise exception 'Organization access required'; end if;
 if tg_op='INSERT' then
  if new.state<>'draft' or new.revision<>1 or new.created_by<>actor or new.last_edited_by<>actor then raise exception 'New records must start as author-owned drafts'; end if;
  if not public.has_org_role(new.organization_id,array['owner','admin','engineer']::public.member_role[]) then raise exception 'Write permission required'; end if;
 else
  if new.id<>old.id or new.organization_id<>old.organization_id or new.created_by<>old.created_by or new.created_at<>old.created_at or new.workflow_key<>old.workflow_key or new.workflow_version<>old.workflow_version or new.parent_id is distinct from old.parent_id then raise exception 'Record identity and origin are immutable'; end if;
  if old.state='closed' then raise exception 'Reviewed closures are immutable; create a linked follow-up'; end if;
  if old.state='in_review' then
   if not public.has_org_role(new.organization_id,array['owner','admin','reviewer']::public.member_role[]) or actor=old.created_by or actor=old.last_edited_by then raise exception 'Independent reviewer required'; end if;
   if new.state not in ('closed','changes_requested') then raise exception 'Choose reviewed closure or request changes'; end if;
   if (to_jsonb(new)-array['state','decision_note','revision','updated_at'])<>(to_jsonb(old)-array['state','decision_note','revision','updated_at']) then raise exception 'Review decisions cannot modify submitted content'; end if;
  else
   if not public.has_org_role(new.organization_id,array['owner','admin','engineer']::public.member_role[]) then raise exception 'Write permission required'; end if;
   if new.state not in ('draft','active','in_review') then raise exception 'Invalid workflow transition'; end if;
   new.last_edited_by:=actor;
  end if;
  if new.state<>old.state and char_length(btrim(new.decision_note))<10 then raise exception 'Document the transition rationale'; end if;
  new.revision:=old.revision+1;
 end if;
 select d.definition into definition from public.medical_operations_definitions d where d.key=new.workflow_key and d.version=new.workflow_version;
 if definition is null then raise exception 'Unknown workflow definition'; end if;
 for field_key,val in select * from jsonb_each(new.fields) loop
  if jsonb_typeof(val)<>'string' or char_length(val#>>'{}')>8000 or not exists(select 1 from jsonb_array_elements(definition->'fields') f where f->>'key'=field_key) then raise exception 'Invalid workflow field'; end if;
 end loop;
 if new.state in ('in_review','closed') then
  for field in select * from jsonb_array_elements(definition->'fields') loop
   if (field->>'required')::boolean and (nullif(btrim(new.fields->>(field->>'key')),'') is null or btrim(new.fields->>(field->>'key')) ~* '^(tbd|todo|n/?a|pending|unknown|not assessed)[.![:space:]]*$') then raise exception 'Complete required fields or document a justified exclusion'; end if;
  end loop;
  if jsonb_array_length(new.evidence_refs)=0 then raise exception 'Link supporting evidence before review'; end if;
 end if;
 for ref in select * from jsonb_array_elements(new.evidence_refs) loop
  source_table:=case ref->>'kind' when 'project' then 'projects' when 'experiment' then 'experiments' when 'report' then 'reports' when 'protocol' then 'protocols' when 'sample' then 'samples' when 'equipment' then 'equipment' when 'lot' then 'lots' when 'build' then 'device_builds' when 'evidence_packet' then 'evidence_packets' else null end;
  if source_table is null or jsonb_typeof(ref)<>'object' or char_length(coalesce(ref->>'label','')) not between 1 and 240 then raise exception 'Invalid evidence reference'; end if;
  execute format('select exists(select 1 from public.%I t where t.id=$1 and t.organization_id=$2 and (to_jsonb(t)->>''deleted_at'') is null)',source_table) into valid_ref using (ref->>'id')::uuid,new.organization_id;
  if not valid_ref then raise exception 'Evidence is unavailable in this organization'; end if;
 end loop;
 new.updated_at:=clock_timestamp();
 return new;
end $$;
revoke all on function labops_ops_private.check_operations_case() from public,anon,authenticated;
create trigger medical_operations_case_guard before insert or update on public.medical_operations_cases for each row execute function labops_ops_private.check_operations_case();

create function labops_ops_private.audit_operations_case() returns trigger language plpgsql security definer set search_path='' as $$
begin
 insert into public.medical_operations_events(organization_id,case_id,revision,actor_id,snapshot)
 values(new.organization_id,new.id,new.revision,public.current_user_id(),to_jsonb(new));
 return null;
end $$;
revoke all on function labops_ops_private.audit_operations_case() from public,anon,authenticated;
create trigger medical_operations_case_audit after insert or update on public.medical_operations_cases for each row execute function labops_ops_private.audit_operations_case();
create index medical_operations_case_queue on public.medical_operations_cases(organization_id,state,priority,due_date);
create index medical_operations_case_origin on public.medical_operations_cases(organization_id,parent_id);
create index medical_operations_event_history on public.medical_operations_events(organization_id,case_id,revision desc);
